{
  "tools": [
    {
      "name": "camera_screenshot",
      "title": "Camera Screenshot",
      "toolset": "scene",
      "description": "Render a camera in the scene and return it as an image. Give any CameraComponent's id or its game object's id, or nothing for the scene's main camera. Works in edit and play mode - editor_camera_screenshot shows the editor viewport instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "camera": {
            "type": "string",
            "description": "A CameraComponent id or its game object's id. Empty uses the scene's main camera."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "includeUi": {
            "type": "boolean",
            "description": "Include any UI the camera renders.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "editor_camera_screenshot",
      "title": "Editor Camera Screenshot",
      "toolset": "scene",
      "description": "Render what the editor scene camera sees and return it as an image - see the scene the way the viewport does. Move the view first with set_editor_camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_find_hidden_faces",
      "title": "Find Hidden Faces",
      "toolset": "hammer",
      "description": "Find mesh faces nobody can see because they're buried inside or pressed flat against other geometry - the underside of a crate sitting on a floor, wall ends tucked into other walls. They still cost rendering and lightmap space. By default this only reports; set apply to paint them nodraw (or another material) in one undo step. A face counts as hidden only if every sample point on it is enclosed by opaque, non-tools mesh geometry, so partly covered faces are left alone. Meshes that aren't closed can fool it - check the result with hammer_focus_nodes and hammer_screenshot before applying on a map you care about.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Mesh node ids to check. Empty checks every mesh."
          },
          "apply": {
            "type": "boolean",
            "description": "Paint the hidden faces with 'material'. False only reports them.",
            "default": false
          },
          "material": {
            "type": "string",
            "description": "The material to paint hidden faces with.",
            "default": "materials/tools/toolsnodraw.vmat"
          },
          "limit": {
            "type": "integer",
            "description": "How many meshes to list in the report.",
            "minimum": 1,
            "maximum": 1000,
            "default": 100
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_focus_nodes",
      "title": "Focus Nodes",
      "toolset": "hammer",
      "description": "Select nodes and frame every Hammer view on them, like the user pressing the frame selection key - the quickest way to show the user something, or to aim hammer_screenshot at it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "The node ids to frame."
          }
        },
        "required": [
          "ids"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_screenshot",
      "title": "Screenshot",
      "toolset": "hammer",
      "description": "Render the map as Hammer's 3D view draws it and return the image - see what you've built. Renders from the main 3D view's camera unless you give a camera, which doesn't move the user's view. Aim it with hammer_focus_nodes or hammer_set_camera first, or pass position and lookAt.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "position": {
            "type": "string",
            "description": "Camera position as 'x,y,z'. Empty uses the 3D view's camera."
          },
          "angles": {
            "type": "string",
            "description": "Camera angles as 'pitch,yaw,roll'."
          },
          "lookAt": {
            "type": "string",
            "description": "A point to look at as 'x,y,z' - overrides angles."
          },
          "fieldOfView": {
            "type": "number",
            "description": "Field of view in degrees. 0 uses the 3D view's.",
            "minimum": 0,
            "maximum": 170,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "ui_pixels",
      "title": "Pixels",
      "toolset": "ui",
      "description": "Read exact pixel values out of a panel - the numbers behind ui_screenshot, for when looking at an image isn't an answer. Points are relative to the panel's top left, which is what makes them comparable to a browser's readout of the same case. Values are 0-255, straight off the rendered frame.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector. Empty uses the first root."
          },
          "points": {
            "type": "string",
            "description": "Points to read, as 'x,y x,y x,y'. Empty reads the panel's centre."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "ui_probe",
      "title": "Probe",
      "toolset": "ui",
      "description": "Draw a scratch panel with the css you give it, measure it, screenshot it, then throw it away. This is how you try a declaration without editing a file and waiting for a hotload - state a case, see what it renders to, compare it against a browser. The sample is a 100x100 block, or a label when you give it text, both inset in a cell like tools/uiparity draws them.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "css": {
            "type": "string",
            "description": "The css to try, e.g. 'border-radius: 20px; background-color: #e8b04a'."
          },
          "text": {
            "type": "string",
            "description": "Text to draw, which makes the sample a label instead of a block."
          },
          "background": {
            "type": "string",
            "description": "Colour behind the sample, so anything with alpha reads against something known.",
            "default": "#101010"
          },
          "points": {
            "type": "string",
            "description": "Pixels to read, as 'x,y x,y' relative to the sample. Empty reads its centre."
          },
          "screenshot": {
            "type": "boolean",
            "description": "Return an image as well as the numbers.",
            "default": true
          }
        },
        "required": [
          "css"
        ]
      }
    },
    {
      "name": "ui_probe_batch",
      "title": "Probe Batch",
      "toolset": "ui",
      "description": "Probe a whole list of css cases at once - one cell each, laid out in a grid, measured together and captured as a single contact sheet. This is the parity sweep: state the cases, get every measurement back in one call, then diff them against the same cases in a browser.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cases": {
            "type": "string",
            "description": "One css case per line. Lines starting with # are ignored, so a case file pastes straight in."
          },
          "text": {
            "type": "string",
            "description": "Text to draw, which makes every sample a label instead of a block."
          },
          "background": {
            "type": "string",
            "description": "Colour behind the samples.",
            "default": "#101010"
          },
          "columns": {
            "type": "integer",
            "description": "Cells per row. 0 fits as many as the screen holds.",
            "minimum": 0,
            "maximum": 24,
            "default": 0
          },
          "points": {
            "type": "string",
            "description": "Pixels to read from every sample, as 'x,y x,y'. Empty reads their centres."
          },
          "screenshot": {
            "type": "boolean",
            "description": "Return the contact sheet as well as the numbers.",
            "default": true
          }
        },
        "required": [
          "cases"
        ]
      }
    },
    {
      "name": "ui_screenshot",
      "title": "Screenshot",
      "toolset": "ui",
      "description": "A screenshot of one panel, cropped to its screen rect, so you can look at what a panel actually draws without hunting for it in a full frame. Renders through the running scene's camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector. Empty uses the first root."
          },
          "padding": {
            "type": "integer",
            "description": "Extra pixels around the panel, for seeing shadows and outlines.",
            "minimum": 0,
            "maximum": 512,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "ui_set_pseudo",
      "title": "Set Pseudo",
      "toolset": "ui",
      "description": "Force a pseudo class on a panel - hover, active, focus - so its styles can be looked at and screenshotted without a mouse. Clears again with on false.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector."
          },
          "pseudo": {
            "type": "string",
            "description": "Which one, e.g. 'Hover'."
          },
          "on": {
            "type": "boolean",
            "description": "Set it, or clear it.",
            "default": true
          }
        },
        "required": [
          "panel",
          "pseudo"
        ]
      }
    }
  ],
  "total": 128
}

{
  "tools": [
    {
      "name": "add_component",
      "title": "Add Component",
      "toolset": "scene",
      "description": "Add a component to a game object, optionally setting its properties in the same call. The user can undo this. Returns the component's id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "type": {
            "type": "string",
            "description": "The component type name, e.g. 'ModelRenderer'. get_component_type documents what exists."
          },
          "properties": {
            "type": "object",
            "description": "Optional json object of property values, e.g. {\"LightColor\": \"1,0.8,0.6,1\", \"Radius\": 512}."
          }
        },
        "required": [
          "id",
          "type"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "GameObject": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "create_game_object",
      "title": "Create Game Object",
      "toolset": "scene",
      "description": "Create a game object in the active scene - empty or from a prefab, optionally with components. For putting a model in the scene, spawn_model is quicker. The user can undo this. Returns the new object's id for the other scene tools.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the new object. Empty picks a sensible default."
          },
          "parent": {
            "type": "string",
            "description": "Parent game object id. Empty parents to the scene root."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'. Default origin."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "scale": {
            "type": "string",
            "description": "Scale as 'x,y,z', or a single number for uniform."
          },
          "components": {
            "type": "string",
            "description": "Comma separated component type names to add, e.g. 'ModelRenderer,BoxCollider'."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "delete_game_object",
      "title": "Delete Game Object",
      "toolset": "scene",
      "description": "Delete a game object and its children. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          }
        },
        "required": [
          "id"
        ]
      }
    },
    {
      "name": "find_game_objects",
      "title": "Find Game Objects",
      "toolset": "scene",
      "description": "Search a scene's game objects by name substring, component type and/or tag. All filters are optional and combine - empty filters list everything. Returns each match with its hierarchy path and id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Case insensitive substring of the object's name."
          },
          "component": {
            "type": "string",
            "description": "Case insensitive substring of a component type name the object must have."
          },
          "tag": {
            "type": "string",
            "description": "A tag the object must have."
          },
          "scene": {
            "type": "string",
            "description": "Scene name or resource path from list_scenes. Empty for the active scene."
          },
          "limit": {
            "type": "integer",
            "description": "How many matches to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many matched in total, beyond what's shown."
          },
          "Results": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Path": {
                  "type": "string",
                  "description": "The object's place in the hierarchy, like 'Map/Props/Barrel'."
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Components": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              },
              "required": []
            }
          },
          "Truncated": {
            "type": "boolean",
            "description": "True when the scene was too big to finish searching."
          }
        },
        "required": []
      }
    },
    {
      "name": "get_game_object",
      "title": "Get Game Object",
      "toolset": "scene",
      "description": "Everything about one game object - enabled state, tags, world transform, parent, children, and its components. Set includeComponentProperties to also get every component's serialized properties.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of every component, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scene": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Id": {
            "type": "string"
          },
          "Enabled": {
            "type": "boolean"
          },
          "ActiveInHierarchy": {
            "type": "boolean"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Parent": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The parent. Null when parented to the scene root."
          },
          "WorldPosition": {
            "type": "string"
          },
          "WorldRotation": {
            "type": "string"
          },
          "WorldScale": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {
                  "description": "The serialized properties. Null unless includeComponentProperties was set."
                }
              },
              "required": []
            }
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_create_game_object",
      "title": "Create Game Object",
      "toolset": "hammer",
      "description": "Put a game object in the open map - empty, from a prefab, and/or with components and their properties set in the same call. This is how s&box gameplay goes in a map. The user can undo the creation. Returns the new node, whose GameObject field is the object's guid.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the object. Empty uses the prefab's name, or 'GameObject'."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search type:prefab."
          },
          "components": {
            "type": "object",
            "description": "Components to add, as a json object of type name to properties - e.g. {\"ModelRenderer\": {\"Model\": \"models/dev/box.vmdl\"}, \"BoxCollider\": {}}. get_component_type documents types and properties. A type the prefab already has gets its properties set instead."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "scene_tree",
      "title": "Scene Tree",
      "toolset": "scene",
      "description": "The game object hierarchy of an open scene - every object's name, id, enabled state and component types, nested like the editor's hierarchy panel. Use the ids with get_game_object to dig into a specific object.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "scene": {
            "type": "string",
            "description": "Scene name or resource path from list_scenes. Empty for the active scene."
          },
          "maxDepth": {
            "type": "integer",
            "description": "How many levels deep to descend. 0 for unlimited.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scene": {
            "type": "string"
          },
          "ResourcePath": {
            "type": "string"
          },
          "Objects": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Components": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                },
                "Children": {
                  "type": "array",
                  "items": {},
                  "description": "Child objects. Null when the depth limit or node budget cut them off."
                },
                "ChildrenNotShown": {
                  "type": "integer",
                  "description": "How many children weren't shown."
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "set_component",
      "title": "Set Component",
      "toolset": "scene",
      "description": "Set properties on a component. Give the component's id, or its game object's id plus a type name. Values use the same serialized forms get_game_object shows - strings, numbers, 'x,y,z' vectors, colors as 'r,g,b,a', asset paths as strings. Everything validates before anything applies, and the user can undo it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The component's id, or its game object's id."
          },
          "properties": {
            "type": "object",
            "description": "A json object of property name to new value."
          },
          "type": {
            "type": "string",
            "description": "The component type to change, when id is a game object."
          }
        },
        "required": [
          "id",
          "properties"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "Applied": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "set_game_object",
